from socket import socket, AF_INET, SOCK_STREAM
import time
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionFailed, RfSwitchActionNotSupported


class AGILENT(RfSwitch):
    """
    Module to control agilent types based RF switches.
    """
    def __init__(self, ip, port=5024):
        super().__init__()
        self.ip = ip
        self.port = int(port)
        self.client_socket = socket(AF_INET, SOCK_STREAM)
        self.client_socket.settimeout(30.0)
        self.client_socket.connect((self.ip, self.port))

    def disconnect_ports(self, port_in, port_out='1'):
        msg = "Action not supported for this device."
        raise RfSwitchActionNotSupported(msg)

    def _send_command(self, command):
        command += "\r\n"
        command = command.encode()
        self.client_socket.send(command)

    def _execute_command(self, command):
        self._send_command(command)
        time.sleep(0.1)
        recv = self.client_socket.recv(1024)
        if len(recv) == 0:
            raise RfSwitchActionFailed("Received empty response from the device.")
        return recv


class AGILENT34980A(AGILENT):
    SUPPORTED_SLOT_VALUES = [str(value) for value in range(1, 9)]
    SUPPORTED_GROUP_VALUES = [str(value) for value in range(1, 5)]
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 5)]
    SUPPORTED_PORT_OUT_VALUES = (None, "1")
    """
    Module to control AGILENT types based RF switches.
    """
    def __init__(self, ip, port=5024):
        super().__init__(ip, port)

    def connect_ports(self, port_in, port_out):
        self._check_port_out(port_out)
        command = self._create_command(port_in, "rout:clos (@", ")")
        self._execute_command(command)

    def get_port_in_status(self, port_in):
        command = self._create_command(port_in, "rout:clos? (@", ")")
        rcv_data = self._execute_command(command)
        port_in_status = str(rcv_data)[-14]
        return port_in_status

    def get_port_out_status(self, port_out):
        self._check_port_out(port_out)
        slot = port_out[0]
        group = port_out[1]
        for port in self.SUPPORTED_PORT_IN_VALUES:
            port_in = slot + group + port
            port_in_status = self.get_port_in_status(port_in)
            if port_in_status == '1':
                return port_in

    def get_connected_ports(self):
        connected_ports = {}
        for slot in self.SUPPORTED_SLOT_VALUES:
            for group in self.SUPPORTED_GROUP_VALUES:
                port_out = str(slot) + str(group) + "1"
                port_in = self.get_port_out_status(port_out)
                if port_in is not None:
                    connected_ports[port_in] = port_out
        return connected_ports

    def _create_command(self, port_in, prefix, postfix):
        slot = port_in[0]
        group = port_in[1]
        port = port_in[2]
        if slot not in self.SUPPORTED_SLOT_VALUES \
                or group not in self.SUPPORTED_GROUP_VALUES \
                or port not in self.SUPPORTED_PORT_IN_VALUES:
            raise RfSwitchActionFailed(f'Given port_in: {port_in} is not supported.')
        command_port = slot + group + '0' + port
        command = prefix + command_port + postfix
        return command

    def _check_port_out(self, port_out):
        slot = port_out[0]
        group = port_out[1]
        port = port_out[2]
        if slot not in self.SUPPORTED_SLOT_VALUES \
                or group not in self.SUPPORTED_GROUP_VALUES \
                or port not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
